 p=argparse.ArgumentParser();p.add_argument('--atlas',type=Path,required=True);p.add_argument('--boreal',type=Path,required=True);a=p.parse_args();root=Path(Path('/tmp/harmonika-level11-root.path').read_text().strip());target=REPO/'docs/LEVEL11-AGENT-EXAM-20261115.json';report=read(target);grades={'atlas':read(a.atlas),'boreal':read(a.boreal)}
